import{_ as a,a as t,c as r,ac as n}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"数学、位运算与几何","description":"从整数约分、素数和组合计数，到快速幂、位集合、几何判定与流式抽样；每类分别核对整数范围、位宽和端点定义。","frontmatter":{"title":"数学、位运算与几何","description":"从整数约分、素数和组合计数，到快速幂、位集合、几何判定与流式抽样；每类分别核对整数范围、位宽和端点定义。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"algorithms","title":"算法","link":"/topics/algorithms/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"问题与数据结构","scope":"general","audience":"general","group":"原理与设计","summary":"从整数约分、素数和组合计数，到快速幂、位集合、几何判定与流式抽样；每类分别核对整数范围、位宽和端点定义。","status":"active","related":[{"title":"Go 算法与容器实践：遍历、排序、递推与堆","link":"/principles/algorithms/exercises/go-interview-algorithm","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组","link":"/principles/algorithms/exercises/leetcode-arrary","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 两数之和至移除元素","link":"/principles/algorithms/exercises/leetcode-arrary-part-01","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 搜索插入位置至完整入口与预期结果","link":"/principles/algorithms/exercises/leetcode-arrary-part-02","kind":"算法推演","scope":"general","audience":"general"},{"title":"0/1 背包","link":"/principles/algorithms/dp/knapsack-01","kind":"问题与数据结构","scope":"general","audience":"general"}],"prev":{"text":"扫描线基础","link":"/principles/algorithms/math/sweep-line"},"next":{"text":"凸包","link":"/principles/algorithms/math/convex-hull"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"扫描线基础","link":"/principles/algorithms/math/sweep-line"},"next":{"text":"凸包","link":"/principles/algorithms/math/convex-hull"}},"headers":[],"relativePath":"principles/algorithms/math/algorithms-math-general-general.md","filePath":"principles/algorithms/math/algorithms-math-general-general.md"}'),i={name:"principles/algorithms/math/algorithms-math-general-general.md"};function p(s,e,o,d,l,c){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="数学、位运算与几何" tabindex="-1">数学、位运算与几何 <a class="header-anchor" href="#数学、位运算与几何" aria-label="Permalink to &quot;数学、位运算与几何&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>每个 package main 独立保存为 main.go，不要合并重名 Point；使用 Go 1.22+。本轮未执行，输出是静态推导。计数与几何乘加要求所有中间值均可用 int 表示，尤其相交测试会相乘两个叉积；筛法要求 n 非负、分解要求 n &gt;= 1、幂指数非负。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>约分、分解一个整数或枚举范围内素数</td><td><a href="#entry-euclidean-gcd-c2eba944ad">最大公约数</a>、<a href="#entry-prime-factorization-6e413f8453">质因数分解</a>、<a href="#entry-prime-sieve-5de0ee26e1">埃氏筛</a></td><td>试除适合单个数，筛法以 O(n) 空间预处理整个范围。</td></tr><tr><td>计算组合数或加速幂与线性递推</td><td><a href="#entry-binomial-coefficient-6742d2f59b">组合数</a>、<a href="#entry-fast-power-323afae0ec">快速幂</a>、<a href="#entry-matrix-power-08fbfa5573">矩阵快速幂</a></td><td>组合数一维倒序更新；快速幂指数非负，矩阵示例为 2×2，均需关注溢出。</td></tr><tr><td>让算术结果保持在模范围</td><td><a href="#entry-modular-arithmetic-4b1ae2bc64">模运算</a></td><td>mod 必须为正，负余数需归一化；逐步取模仍不能忽略中间加法溢出。</td></tr><tr><td>紧凑保存布尔状态、比较置位差异或枚举子集</td><td><a href="#entry-bitmask-665900f461">位掩码</a>、<a href="#entry-hamming-distance-786d047d7c">汉明距离</a>、<a href="#entry-subset-bit-enumeration-6e29b0b414">子集位枚举</a></td><td>位宽有限；子集位枚举只输出非空子集，结果仍指数增长。</td></tr><tr><td>判断方向、线段接触或点集边界</td><td><a href="#entry-dot-cross-product-755f552125">点积与叉积</a>、<a href="#entry-segment-intersection-612510935e">线段相交</a>、<a href="#entry-convex-hull-56ebb4d6fc">凸包</a></td><td>示例相交包含端点与共线重叠；凸包省略共线中间点且会重排输入。</td></tr><tr><td>统计同时活跃的区间数量</td><td><a href="#entry-sweep-line-cce3de4f28">扫描线</a></td><td>示例采用半开区间，同坐标先处理终点；端点定义决定事件顺序。</td></tr><tr><td>从未知长度的数据流等概率取一个样本</td><td><a href="#entry-reservoir-sampling-68cd516091">蓄水池抽样</a></td><td>第 i 项以 1/i 概率替换；固定随机种子用于复现，可另传随机源。</td></tr></tbody></table><h2 id="scene-integer-factors-and-counts" tabindex="-1">求公约数、质因子、素数与组合数 <a class="header-anchor" href="#scene-integer-factors-and-counts" aria-label="Permalink to &quot;求公约数、质因子、素数与组合数 {#scene-integer-factors-and-counts}&quot;">​</a></h2><h3 id="entry-euclidean-gcd-c2eba944ad" tabindex="-1">欧几里得算法 <a class="header-anchor" href="#entry-euclidean-gcd-c2eba944ad" aria-label="Permalink to &quot;欧几里得算法 {#entry-euclidean-gcd-c2eba944ad}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-euclidean-gcd-c2eba944ad-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/euclidean-gcd">欧几里得算法</a>。</p><p>gcd(a,b)=gcd(b,a mod b)，因为能同时整除 a 和 b 的数也能整除余数。每轮让第二个数变小，直到余数为零。 结束时的非零值即最大公约数。</p><p>它还能配合最小公倍数计算和分数约分；涉及负数时示例把最终结果转成非负，但最小 int 的绝对值可能无法用 int 表示，本例不接受该极值。GCD(0,0) 按实现返回 0。</p><h3 id="entry-prime-factorization-6e413f8453" tabindex="-1">质因数分解 <a class="header-anchor" href="#entry-prime-factorization-6e413f8453" aria-label="Permalink to &quot;质因数分解 {#entry-prime-factorization-6e413f8453}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-prime-factorization-6e413f8453-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/prime-factorization">质因数分解</a>。</p><p>示例返回带重复次数的因子列表；非常大的整数通常需要更先进的分解算法。</p><h3 id="entry-prime-sieve-5de0ee26e1" tabindex="-1">埃氏筛 <a class="header-anchor" href="#entry-prime-sieve-5de0ee26e1" aria-label="Permalink to &quot;埃氏筛 {#entry-prime-sieve-5de0ee26e1}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-prime-sieve-5de0ee26e1-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/prime-sieve">埃氏筛</a>。</p><p>预处理时间约 O(n log log n)、空间 O(n)，适合一次求出范围内许多素数。</p><h3 id="entry-binomial-coefficient-6742d2f59b" tabindex="-1">组合数 <a class="header-anchor" href="#entry-binomial-coefficient-6742d2f59b" aria-label="Permalink to &quot;组合数 {#entry-binomial-coefficient-6742d2f59b}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-binomial-coefficient-6742d2f59b-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/binomial-coefficient">组合数</a>。</p><p>组合数满足帕斯卡恒等式：选择某元素或不选它，得到相邻两项之和。用一维数组倒序更新，避免本轮新值覆盖还需要读取的上一轮状态。 空间 O(k)。</p><p>结果增长很快，n 较大时 Go int 会溢出。</p><h2 id="scene-fast-arithmetic" tabindex="-1">用模运算与快速幂控制计算过程 <a class="header-anchor" href="#scene-fast-arithmetic" aria-label="Permalink to &quot;用模运算与快速幂控制计算过程 {#scene-fast-arithmetic}&quot;">​</a></h2><h3 id="entry-modular-arithmetic-4b1ae2bc64" tabindex="-1">模运算 <a class="header-anchor" href="#entry-modular-arithmetic-4b1ae2bc64" aria-label="Permalink to &quot;模运算 {#entry-modular-arithmetic-4b1ae2bc64}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-modular-arithmetic-4b1ae2bc64-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/modular-arithmetic">模运算</a>。</p><p>模运算把整数结果限制在 0 到 mod−1 的范围内，常用于计数、哈希和数论。加法与乘法可以逐步取模；示例乘法按位累加，避免直接计算 a×b。 负数取模后还需归一化到非负余数。</p><p>mod 必须为正，ModMultiply 的 b 必须非负；负 b 会跳过循环而不能得到正确乘积。对极大 int 的中间加法仍要注意溢出，本例要求归一化和相加的中间值均可由 int 表示。</p><h3 id="entry-fast-power-323afae0ec" tabindex="-1">快速幂 <a class="header-anchor" href="#entry-fast-power-323afae0ec" aria-label="Permalink to &quot;快速幂 {#entry-fast-power-323afae0ec}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-fast-power-323afae0ec-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/fast-power">快速幂</a>。</p><p>把指数写成二进制：某一位为 1 时，把当前底数乘入答案；每轮底数平方、指数右移。这样只需对数次乘法。 时间 O(log exponent)。</p><p>示例处理非负整数指数且使用普通 int，负指数或溢出风险需要另行处理。</p><h3 id="entry-matrix-power-08fbfa5573" tabindex="-1">矩阵快速幂 <a class="header-anchor" href="#entry-matrix-power-08fbfa5573" aria-label="Permalink to &quot;矩阵快速幂 {#entry-matrix-power-08fbfa5573}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-matrix-power-08fbfa5573-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/matrix-power">矩阵快速幂</a>。</p><p>示例处理 2×2 矩阵；大数计算需要考虑溢出或取模。</p><h2 id="scene-encode-bit-sets" tabindex="-1">表示位集合、比较差异与枚举子集 <a class="header-anchor" href="#scene-encode-bit-sets" aria-label="Permalink to &quot;表示位集合、比较差异与枚举子集 {#scene-encode-bit-sets}&quot;">​</a></h2><h3 id="entry-bitmask-665900f461" tabindex="-1">位掩码 <a class="header-anchor" href="#entry-bitmask-665900f461" aria-label="Permalink to &quot;位掩码 {#entry-bitmask-665900f461}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-bitmask-665900f461-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/bitmask">位掩码</a>。</p><p>第 i 位可以表示第 i 个功能是否启用、元素是否已选等布尔状态。按位或设置该位，按位清除移除它，按位与检查它。 单个机器字中的添加、移除和判断均为 O(1)。</p><p>一个机器字只能容纳有限个状态；超过字长时要使用多个字或位集合。</p><h3 id="entry-power-of-two-6cf5764341" tabindex="-1">判断 2 的幂 <a class="header-anchor" href="#entry-power-of-two-6cf5764341" aria-label="Permalink to &quot;判断 2 的幂 {#entry-power-of-two-6cf5764341}&quot;">​</a></h3><p><span id="输出-8"></span><span id="示例-8"></span></p><p><span id="entry-power-of-two-6cf5764341-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/power-of-two">判断 2 的幂</a>。</p><p>必须先排除零，否则无符号整数的减法会下溢，且零本身也不是 2 的幂。</p><h3 id="entry-hamming-distance-786d047d7c" tabindex="-1">汉明距离 <a class="header-anchor" href="#entry-hamming-distance-786d047d7c" aria-label="Permalink to &quot;汉明距离 {#entry-hamming-distance-786d047d7c}&quot;">​</a></h3><p><span id="输出-9"></span><span id="示例-9"></span></p><p><span id="entry-hamming-distance-786d047d7c-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/hamming-distance">汉明距离</a>。</p><p>比较很长的二进制串时，可以分块处理并累加每块的置位数。</p><h3 id="entry-subset-bit-enumeration-6e29b0b414" tabindex="-1">位运算枚举子集 <a class="header-anchor" href="#entry-subset-bit-enumeration-6e29b0b414" aria-label="Permalink to &quot;位运算枚举子集 {#entry-subset-bit-enumeration-6e29b0b414}&quot;">​</a></h3><p><span id="输出-10"></span><span id="示例-10"></span></p><p><span id="entry-subset-bit-enumeration-6e29b0b414-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/subset-bit-enumeration">位运算枚举子集</a>。</p><p>给定 mask，(sub−1)&amp;mask 会得到下一个更小且只包含原掩码置位的子集。循环直到 sub 为零，能枚举全部非空子集。 包含 k 个置位时枚举耗时 O(2^k)。</p><p>包含 k 个置位时共有 2ᵏ−1 个结果，指数增长仍然不可避免。</p><h2 id="scene-geometry-and-events" tabindex="-1">判断几何关系与统计区间重叠 <a class="header-anchor" href="#scene-geometry-and-events" aria-label="Permalink to &quot;判断几何关系与统计区间重叠 {#scene-geometry-and-events}&quot;">​</a></h2><h3 id="entry-dot-cross-product-755f552125" tabindex="-1">点积与叉积 <a class="header-anchor" href="#entry-dot-cross-product-755f552125" aria-label="Permalink to &quot;点积与叉积 {#entry-dot-cross-product-755f552125}&quot;">​</a></h3><p><span id="输出-11"></span><span id="示例-11"></span></p><p><span id="entry-dot-cross-product-755f552125-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/dot-cross-product">点积与叉积</a>。</p><p>点积 a·b 与向量夹角和投影有关，常用于判断朝向与计算长度。二维叉积 a×b 的符号区分从 a 转向 b 是左转、右转还是共线。 二维向量上的这些运算均为常数时间。</p><p>坐标值很大时，乘法可能超出 int 范围，需要更宽的数值类型。</p><h3 id="entry-segment-intersection-612510935e" tabindex="-1">线段相交 <a class="header-anchor" href="#entry-segment-intersection-612510935e" aria-label="Permalink to &quot;线段相交 {#entry-segment-intersection-612510935e}&quot;">​</a></h3><p><span id="输出-12"></span><span id="示例-12"></span></p><p><span id="entry-segment-intersection-612510935e-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/segment-intersection">线段相交</a>。</p><p>示例把端点接触和共线重叠都视为相交。</p><h3 id="entry-convex-hull-56ebb4d6fc" tabindex="-1">凸包 <a class="header-anchor" href="#entry-convex-hull-56ebb4d6fc" aria-label="Permalink to &quot;凸包 {#entry-convex-hull-56ebb4d6fc}&quot;">​</a></h3><p><span id="输出-13"></span><span id="示例-13"></span></p><p><span id="entry-convex-hull-56ebb4d6fc-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/convex-hull">凸包</a>。</p><p>单调链先按 x、y 排序，再依次构建下凸壳和上凸壳。遇到非左转时删除中间点，保证边界始终凸。 时间 O(n log n)。</p><p>示例会修改输入切片的顺序，并省略同一直线上的中间边界点；是否保留这些点取决于应用。</p><h3 id="entry-sweep-line-cce3de4f28" tabindex="-1">扫描线基础 <a class="header-anchor" href="#entry-sweep-line-cce3de4f28" aria-label="Permalink to &quot;扫描线基础 {#entry-sweep-line-cce3de4f28}&quot;">​</a></h3><p><span id="输出-14"></span><span id="示例-14"></span></p><p><span id="entry-sweep-line-cce3de4f28-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/sweep-line">扫描线基础</a>。</p><p>最大活跃数就是最大并发覆盖数量。</p><h2 id="scene-sample-stream" tabindex="-1">从未知长度的数据流抽取一个样本 <a class="header-anchor" href="#scene-sample-stream" aria-label="Permalink to &quot;从未知长度的数据流抽取一个样本 {#scene-sample-stream}&quot;">​</a></h2><h3 id="entry-reservoir-sampling-68cd516091" tabindex="-1">蓄水池抽样 <a class="header-anchor" href="#entry-reservoir-sampling-68cd516091" aria-label="Permalink to &quot;蓄水池抽样 {#entry-reservoir-sampling-68cd516091}&quot;">​</a></h3><p><span id="输出-15"></span><span id="示例-15"></span></p><p><span id="entry-reservoir-sampling-68cd516091-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/math/reservoir-sampling">蓄水池抽样</a>。</p><p>处理第 i 个元素时，以 1/i 的概率替换当前样本。归纳可知，处理完 i 个元素后每个元素仍以 1/i 的概率被保留，因此无需事先知道流长度。 无需保存整条数据流。</p><p>示例固定随机种子便于复现；实际场景可传入自己的随机源。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>ModMultiply(8,-7,10) 是否满足本例前提？再判断半开区间 [1,2) 与 [2,3) 是否重叠。提示：看循环条件和同坐标事件顺序。</p><details class="details custom-block"><summary>参考解法</summary><p>不满足，b 必须非负，负数会直接跳过循环；两个半开区间不重叠，同坐标先处理终点再处理起点。需要支持有符号乘法应另设计归一化契约。</p></details>',101)])])}const f=a(i,[["render",p]]);export{m as __pageData,f as default};
